local HairpinMaker = {}
local PRODUCTS = {
    iron_hairpin = { name = "Železna lasnica", ironCost = 3, woodCost = 1, leatherCost = 1, time = 4, cost = 130, prestige = 3, happiness = 2, description = "Železna lasnica za pritrditev las." },
    bronze_hairpin = { name = "Bronasta lasnica", bronzeCost = 3, ironCost = 1, woodCost = 1, leatherCost = 1, time = 6, cost = 320, prestige = 5, happiness = 3, description = "Bronasta lasnica za fine pričeske." },
    silver_hairpin = { name = "Srebrna lasnica", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 10, cost = 780, prestige = 10, happiness = 4, description = "Srebrna lasnica za plemiške pričeske." },
    gilded_hairpin = { name = "Pozlačena lasnica", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 14, cost = 1700, prestige = 19, happiness = 5, description = "Pozlačena lasnica za dvorne pričeske." },
    jewel_set_hairpin = { name = "Draguljasta lasnica", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 18, cost = 3700, prestige = 35, happiness = 7, description = "Draguljasta lasnica za kraljeve pričeske." },
    royal_sovereign_hairpin = { name = "Kraljevski suverena lasnica", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 25, cost = 8000, prestige = 67, happiness = 13, description = "Suverena lasnica z biseri za krono." },
}
local BUILDINGS = {
    hairpin_workshop = { name = "Lasnična delavnica", cost = { gold = 300, wood = 175, stone = 125, iron = 8 }, upkeep = 5, qualityBonus = 5 },
    hairpin_house = { name = "Lasnična hiša", cost = { gold = 1110, wood = 355, stone = 255, silver = 6, iron = 7 }, upkeep = 23, qualityBonus = 18 },
    master_hairpin_atelier = { name = "Mojstrski lasnični atelje", cost = { gold = 2860, wood = 415, stone = 495, silver = 33, gold = 6 }, upkeep = 67, qualityBonus = 30 },
    sovereign_hairpin_palace = { name = "Suverena lasnična palača", cost = { gold = 12450, wood = 640, stone = 800, gold = 80, jewel = 18 }, upkeep = 245, qualityBonus = 55, prestigeBonus = 50 },
}
HairpinMaker.ironStock = 14; HairpinMaker.bronzeStock = 12; HairpinMaker.woodStock = 10; HairpinMaker.leatherStock = 8; HairpinMaker.silverStock = 8; HairpinMaker.goldStock = 6; HairpinMaker.jewelStock = 4; HairpinMaker.pearlStock = 4
HairpinMaker.productStock = {}; HairpinMaker.buildings = {}; HairpinMaker.maker = nil; HairpinMaker.activeMaking = {}; HairpinMaker.totalProducts = 0; HairpinMaker.dayTimer = 0
function HairpinMaker.init() HairpinMaker.ironStock=14; HairpinMaker.bronzeStock=12; HairpinMaker.woodStock=10; HairpinMaker.leatherStock=8; HairpinMaker.silverStock=8; HairpinMaker.goldStock=6; HairpinMaker.jewelStock=4; HairpinMaker.pearlStock=4; HairpinMaker.productStock={}; HairpinMaker.buildings={}; HairpinMaker.maker=nil; HairpinMaker.activeMaking={}; HairpinMaker.totalProducts=0; HairpinMaker.dayTimer=0; print("[HairpinMaker] Royal Hairpin Maker System initialized (6 products, 4 buildings)") end
function HairpinMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HairpinMaker.maker={name=n or ("Lasničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lasničar najet: %s (spretnost: %d)",HairpinMaker.maker.name,s),"success") end; return true end
function HairpinMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HairpinMaker.build(id) local ok,e=HairpinMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HairpinMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HairpinMaker.getQualityBonus() local b=0; for _,bd in ipairs(HairpinMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HairpinMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HairpinMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HairpinMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HairpinMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HairpinMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HairpinMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HairpinMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HairpinMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HairpinMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HairpinMaker.buildings==0 then return false,"Potrebna lasnična delavnica" end; if not HairpinMaker.maker then return false,"Potreben lasničar" end; return true end
function HairpinMaker.make(pt,qty) qty=qty or 1; local ok,e=HairpinMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HairpinMaker.ironStock=HairpinMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HairpinMaker.bronzeStock=HairpinMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HairpinMaker.woodStock=HairpinMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HairpinMaker.leatherStock=HairpinMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HairpinMaker.silverStock=HairpinMaker.silverStock-d.silverCost*qty end; if d.goldCost then HairpinMaker.goldStock=HairpinMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HairpinMaker.jewelStock=HairpinMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HairpinMaker.pearlStock=HairpinMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HairpinMaker.maker then t=math.max(1,t-math.floor(HairpinMaker.maker.skill/13)) end; table.insert(HairpinMaker.activeMaking,{id="hairpin_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HairpinMaker.completeMaking(m) local q=1.0+(HairpinMaker.getQualityBonus()/100); if HairpinMaker.maker then q=q+(HairpinMaker.maker.skill/140) end; q=math.min(2.5,q); HairpinMaker.productStock[m.productType]=(HairpinMaker.productStock[m.productType] or 0)+m.quantity; HairpinMaker.totalProducts=HairpinMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HairpinMaker.maker then HairpinMaker.maker.itemsMade=HairpinMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HairpinMaker.maker.skill=math.min(100,HairpinMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lasnica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"hairpin.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function HairpinMaker.update(dt) if not _G.state then return end; HairpinMaker.dayTimer=HairpinMaker.dayTimer+dt; if HairpinMaker.dayTimer>=30 then HairpinMaker.dayTimer=0; for i=#HairpinMaker.activeMaking,1,-1 do local m=HairpinMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HairpinMaker.completeMaking(m); table.remove(HairpinMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HairpinMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HairpinMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HairpinMaker.getStats() return {ironStock=HairpinMaker.ironStock,bronzeStock=HairpinMaker.bronzeStock,woodStock=HairpinMaker.woodStock,leatherStock=HairpinMaker.leatherStock,silverStock=HairpinMaker.silverStock,goldStock=HairpinMaker.goldStock,jewelStock=HairpinMaker.jewelStock,pearlStock=HairpinMaker.pearlStock,productStock=HairpinMaker.productStock,numBuildings=#HairpinMaker.buildings,hasMaker=HairpinMaker.maker~=nil,makerName=HairpinMaker.maker and HairpinMaker.maker.name or "—",makerSkill=HairpinMaker.maker and HairpinMaker.maker.skill or 0,activeMaking=#HairpinMaker.activeMaking,totalProducts=HairpinMaker.totalProducts} end
return HairpinMaker
